LRU = ("from collections import OrderedDict\n\n"
       "class LRUCache:\n"
       "    def __init__(self, capacity):\n"
       "        self.cap, self.data = capacity, OrderedDict()\n"
       "        self.hits = self.misses = 0\n"
       "    def get(self, key, load):\n"
       "        if key in self.data:\n"
       "            self.hits += 1\n"
       "            self.data.move_to_end(key)        # жақында қолданылды\n"
       "            return self.data[key]\n"
       "        self.misses += 1\n"
       "        value = load(key)                     # баяу дереккөз (дерекқор)\n"
       "        self.data[key] = value\n"
       "        if len(self.data) > self.cap:\n"
       "            self.data.popitem(last=False)     # ең ұзақ қолданылмағанды шығару\n"
       "        return value\n\n"
       "db_calls = []\n"
       "def load(k):\n"
       "    db_calls.append(k)\n"
       "    return k.upper()\n\n"
       "c = LRUCache(2)\n"
       "for k in ['a', 'b', 'a', 'c', 'b', 'a', 'a']:\n"
       "    c.get(k, load)\n"
       "print('дерекқорға:', db_calls)\n"
       "print('hit =', c.hits, ' miss =', c.misses, ' кэште:', list(c.data))")

